const $=s=>document.querySelector(s),app=$('#app'),base='https://raw.githubusercontent.com/Fr0uu/streak-in/main/public/images/';
const skills=[{id:'lsit',name:'L-Sit',desc:'Bangun core kuat. Angkat batasmu.',image:'skills/lsit-skill-full-hold.png',stages:['Support hold','Tuck L-Sit','One-leg L-Sit','Straddle L-Sit','Full L-Sit']},{id:'handstand',name:'Handstand',desc:'Temukan keseimbangan, satu tahap lagi.',image:'skills/hs-skill-chest-to-wall.png',stages:['Wall walk hold','Chest-to-wall hold','Toe taps','Controlled kick-up','Freestanding handstand']},{id:'elbow',name:'Elbow Lever',desc:'Kontrol tubuhmu. Rasakan progresnya.',image:'exercises/forearm-plank.png',stages:['Plank lean','Knee elbow lever','Tuck elbow lever','Straddle elbow lever','Full elbow lever']}];
const sessions=[{id:'push',name:'Push & Core',mins:15,focus:'Kekuatan dasar',ex:['Incline push-up','Push-up','Dead bug','Plank'],image:'exercises/push-up-low.png'},{id:'core',name:'Core Foundations',mins:10,focus:'Stabilitas & kontrol',ex:['Dead bug','Hollow tuck hold','Glute bridge','Plank'],image:'exercises/hollow-tuck-hold.png'},{id:'skill',name:'L-Sit Foundations',mins:15,focus:'Skill mastery',ex:['Wrist warm-up','Support hold','Tuck L-Sit','Hollow tuck hold'],image:'skills/lsit-skill-support-hold.png'},{id:'full',name:'Full Body Reset',mins:30,focus:'Seluruh tubuh',ex:['Push-up','Reverse lunge','Glute bridge','Plank'],image:'exercises/reverse-lunge-bottom.png'}];
let data;try{data=JSON.parse(localStorage.getItem('streakin_prototype_v1'))||{logs:[],stages:{},saved:['push','skill'],reminder:'16:00'}}catch{data={logs:[],stages:{},saved:['push','skill'],reminder:'16:00'}}let filter=0,work=null,elapsed=0,running=false,rest=0,ticker=null,started=0;
function save(){localStorage.setItem('streakin_prototype_v1',JSON.stringify(data))}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('toast-show');setTimeout(()=>$('#toast').classList.remove('toast-show'),2600)}
function today(){return new Date().toLocaleDateString('en-CA')}function streak(){let n=0,d=new Date();if(!data.logs.some(l=>l.day===today()))d.setDate(d.getDate()-1);while(data.logs.some(l=>l.day===d.toLocaleDateString('en-CA'))){n++;d.setDate(d.getDate()-1)}return n}
const heading=(ey,title,sub)=>`<div class="heading"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p>${sub}</p></div><span class="date">${new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long'})}</span></div>`;
function skillCard(s,i){let stage=data.stages[s.id]||1;return `<a class="skill panel" href="#skill/${s.id}"><div class="skill-art"><span class="tag">0${i+1} / SKILL MASTERY</span><img src="${base+s.image}" alt="Ilustrasi ${s.name}" loading="lazy"></div><div class="skill-body"><h3>${s.name} <span class="orange" style="float:right">↗</span></h3><p>${s.desc}</p><div class="progress"><div style="width:${(stage-1)*25}%"></div></div><div class="skill-meta"><span>Stage ${stage} dari 5</span><span>${stage===1?'Mulai perjalanan':s.stages[stage-1]}</span></div></div></a>`}
function home(){let d=new Date(),days='Sen Sel Rab Kam Jum Sab Min'.split(' '),monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));app.innerHTML=heading('MAKE ROOM FOR YOURSELF','Sedikit waktu. Banyak progres.','Jadwal boleh padat. Gerak tetap dapat tempat.')+`<div class="grid"><section class="hero"><div class="eyebrow">SESI PILIHAN HARI INI · 15 MENIT</div><h2>Mulai kecil.<br>Jadi lebih kuat.</h2><p>Empat gerakan sederhana untuk tubuh yang lebih siap menjalani harimu.</p><button class="primary" data-start="push">▶ &nbsp; Mulai latihan &nbsp; ↗</button><img src="${base}mascot/ppt-welcome.png" alt="Orange Guy menyambutmu"></section><section class="panel"><div class="panel-top"><h3>Keep the fire alive.</h3><span class="orange">ϟ</span></div><div class="streak-num">${streak()} <span>hari konsisten</span></div><p class="note">${streak()?'Langkah kecilmu mulai jadi kebiasaan.':'Satu sesi hari ini adalah awal yang bagus.'}</p><div class="days">${days.map((n,i)=>{let t=new Date(monday);t.setDate(t.getDate()+i);return `<div class="day ${data.logs.some(l=>l.day===t.toLocaleDateString('en-CA'))?'done':''}"><b>${data.logs.some(l=>l.day===t.toLocaleDateString('en-CA'))?'✓':'·'}</b>${n}</div>`}).join('')}</div><p class="note" style="margin:22px 0 0;border-top:1px solid var(--line);padding-top:15px">Istirahat juga bagian dari progres. Dengarkan tubuhmu.</p></section></div><div class="stats"><div class="stat"><i>◷</i><div><strong>${data.logs.reduce((n,l)=>n+l.mins,0)} <span style="font-size:12px">menit</span></strong><small>Waktu untuk dirimu</small></div></div><div class="stat"><i>✓</i><div><strong>${data.logs.length}</strong><small>Sesi diselesaikan</small></div></div><div class="stat"><i>◈</i><div><strong>${Object.values(data.stages).filter(n=>n>1).length} / 3</strong><small>Skill dalam perjalanan</small></div></div></div><div class="section-head"><h2>Gerakan keren dimulai dari dasar.</h2><a class="text-link" href="#skills">Semua roadmap ↗</a></div><div class="cards">${skills.map(skillCard).join('')}</div><div class="bottom-note"><b>↗</b><div><strong>10 menit tetap berarti.</strong><br><span style="color:var(--muted)">Punya sedikit waktu? Pilih sesi singkat yang cocok untuk harimu.</span></div><a class="text-link" style="margin-left:auto;white-space:nowrap" href="#library">Cari latihan →</a></div>`}
function library(){app.innerHTML=heading('YOUR TIME, YOUR PACE','Ada waktu berapa hari ini?','Pilih latihan yang pas. Tidak perlu menunggu jadwal kosong.')+`<div class="filters">${[0,10,15,30].map(n=>`<button class="filter ${filter===n?'active':''}" data-filter="${n}">${n?n+' menit':'Semua durasi'}</button>`).join('')}</div>${sessions.filter(s=>!filter||s.mins===filter).map((s,i)=>`<section class="panel session"><span class="number">0${i+1}</span><div><h3>${s.name}</h3><p>${s.mins} menit · ${s.focus} · ${s.ex.length} gerakan</p></div><button class="secondary" data-save="${s.id}" aria-label="Simpan ${s.name}">${data.saved.includes(s.id)?'★':'☆'}</button><button class="primary" data-start="${s.id}">Mulai →</button></section>`).join('')}<div class="bottom-note">Sesi latihan ini adalah panduan prototipe. Sesuaikan intensitas dengan kemampuanmu; hentikan jika terasa nyeri.</div>`}
function roadmap(id){const s=skills.find(s=>s.id===id);if(!s){location.hash='skills';return}let stage=data.stages[id]||1;app.innerHTML=heading('SKILL ROADMAP',s.name,'Lima langkah terarah. Bangun fondasi sebelum melangkah lebih jauh.')+`<div class="split"><div class="player-art" style="height:380px;margin:0"><img src="${base+s.image}" alt="${s.name}"></div><div><span class="tag">STAGE ${stage} / 5</span><h2>${s.stages[stage-1]}</h2><p>Fokus pada kontrol dan teknik, bukan sekadar durasi. Mulai dari posisi yang bisa kamu pertahankan dengan nyaman.</p><button class="primary" data-start="skill">Latih fondasimu →</button><p class="note">Progres tahap dicatat sendiri pada prototipe ini. Ilustrasi Elbow Lever khusus masih perlu dilengkapi; gambar saat ini menunjukkan fondasi plank.</p></div></div><div class="roadmap">${s.stages.map((n,i)=>`<section class="panel stage"><div class="number">${i<stage-1?'✓':i+1}</div><div><h3>${n}</h3><p>${i===0?'Bangun tumpuan dan kontrol dasar.':'Tingkatkan kontrol secara bertahap setelah tahap sebelumnya nyaman.'}</p></div><button class="secondary" data-stage="${id}:${i+1}">${stage===i+1?'Tahap aktif':'Pilih tahap'}</button></section>`).join('')}</div>`}
function history(){app.innerHTML=heading('EVERY SESSION COUNTS','Lihat seberapa jauh kamu bergerak.','Progres kecil tetap progres. Catatan ini tersimpan di browser ini.')+(data.logs.length?data.logs.slice().reverse().map(l=>`<section class="panel session"><span class="orange">✓</span><div><h3>${l.name}</h3><p>${l.day} · ${l.mins} menit · ${l.sets} set selesai</p></div><span class="tag">SELESAI</span></section>`).join(''):`<section class="panel empty"><div class="eyebrow">HALAMAN PERTAMA CERITAMU</div><h2>Belum ada sesi. Belum terlambat.</h2><p>Mulai latihan pertamamu, lalu lihat progresnya di sini.</p><button class="primary" data-start="core">Mulai 10 menit →</button></section>`)+`<section class="panel" style="margin-top:25px"><h3>Waktu untuk bergerak</h3><p class="note">Simpan waktu pilihanmu. Prototipe ini belum mengirim notifikasi.</p><label for="reminder">Jam latihan &nbsp;</label><input id="reminder" type="time" value="${data.reminder}" style="padding:10px;background:var(--bg);color:white;border:1px solid var(--line);border-radius:7px"><button class="secondary" id="remind" style="margin-left:10px">Simpan</button></section>`}
function start(id){work={...sessions.find(s=>s.id===id),index:0,sets:0};elapsed=0;running=false;rest=0;started=Date.now();location.hash='workout';if(location.hash==='#workout')player()}
function player(){if(!work){location.hash='library';return}app.innerHTML=`<div class="player"><div class="panel-top"><a href="#library" class="text-link">← Kembali ke library</a><span class="tag">${work.name}</span></div><div class="section-head"><span class="eyebrow">GERAKAN ${work.index+1} DARI ${work.ex.length}</span><span class="note">${work.sets} set tercatat</span></div><div class="progress"><div style="width:${work.index/work.ex.length*100}%"></div></div><div class="player-art"><img src="${base+work.image}" alt="Ilustrasi sesi ${work.name}"></div><h2>${work.ex[work.index]}</h2><p class="note" style="text-align:center">3 set · 8 repetisi atau 20 detik hold · istirahat 45 detik</p><div class="timer" id="timer">00:00</div><p id="timer-label" style="text-align:center;font-size:12px">Siap saat kamu siap.</p><div class="actions"><button class="primary" id="timer-toggle">▶ Mulai timer</button><button class="secondary" id="rest">Istirahat 45 dtk</button><button class="secondary" id="reset">Reset timer</button></div><section class="panel"><h3>Fokus teknik</h3><p class="note">Jaga core aktif. Bergerak perlahan dan bernapas teratur. Pilih variasi lebih mudah saat teknik mulai berubah.</p><div class="set-row"><label for="reps">Repetisi / detik hold</label><input id="reps" type="number" min="1" max="300" value="8"><button class="secondary" id="log-set">Catat set ✓</button></div></section><div class="actions"><button class="primary" id="next">${work.index===work.ex.length-1?'Selesaikan sesi ✓':'Gerakan berikutnya →'}</button></div><p class="note" style="text-align:center">Ilustrasi saat ini mewakili sesi; pemetaan pose per gerakan akan dilengkapi.</p></div>`;drawTimer()}
function drawTimer(){if(!$('#timer'))return;let n=rest||elapsed;$('#timer').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');$('#timer-label').textContent=rest?'Waktu pemulihan. Tarik napas.':running?'Jaga teknik. Kamu punya kendali.':'Siap saat kamu siap.';$('#timer-toggle').textContent=running?'Ⅱ Jeda timer':'▶ Mulai timer'}
setInterval(()=>{if(location.hash!=='#workout')return;if(rest>0){rest--;if(rest===0){toast('Waktu istirahat selesai.');try{navigator.vibrate?.(150)}catch{}}drawTimer()}else if(running){elapsed=Math.floor((Date.now()-ticker)/1000);drawTimer()}},1000);
function finish(){running=false;rest=0;let log={name:work.name,mins:Math.max(1,Math.round((Date.now()-started)/60000)),sets:work.sets,day:today()};data.logs.push(log);save();work=null;location.hash='complete'}
function render(){const route=location.hash.slice(1)||'home';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',route===a.dataset.page||route.startsWith('skill/')&&a.dataset.page==='skills'));if(route==='home')home();else if(route==='library')library();else if(route==='skills'){app.innerHTML=heading('BUILD SKILLS, NOT SHORTCUTS','Tujuan besar. Langkah yang jelas.','Pilih satu skill. Mulai dari fondasinya.')+`<div class="cards">${skills.map(skillCard).join('')}</div>`}else if(route.startsWith('skill/'))roadmap(route.split('/')[1]);else if(route==='history')history();else if(route==='workout')player();else if(route==='complete')app.innerHTML=`<div class="summary"><div class="badge">✳</div><div class="eyebrow">ONE MORE STEP FORWARD</div><h1>Kamu datang. Kamu bergerak.</h1><p>Satu sesi lagi untuk dirimu. Rayakan langkah kecil hari ini.</p><div class="actions"><a class="primary" href="#history">Lihat progres →</a><a class="secondary" href="#home">Kembali ke beranda</a></div></div>`;else home();window.scrollTo(0,0)}
window.addEventListener('hashchange',render);document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.start)start(b.dataset.start);if(b.dataset.filter){filter=Number(b.dataset.filter);library()}if(b.dataset.save){const id=b.dataset.save;data.saved=data.saved.includes(id)?data.saved.filter(x=>x!==id):[...data.saved,id];save();library();toast('Library diperbarui.')}if(b.dataset.stage){let[id,n]=b.dataset.stage.split(':');data.stages[id]=+n;save();roadmap(id);toast('Tahap aktif disimpan.')}if(b.id==='timer-toggle'){if(rest){rest=0}running=!running;ticker=Date.now()-elapsed*1000;drawTimer()}if(b.id==='rest'){running=false;rest=45;drawTimer()}if(b.id==='reset'){running=false;elapsed=0;rest=0;drawTimer()}if(b.id==='log-set'){let n=Number($('#reps').value);if(!Number.isFinite(n)||n<1||n>300){toast('Masukkan nilai 1–300.');return}work.sets++;running=false;rest=45;player();toast('Set tercatat. Waktunya istirahat.')}if(b.id==='next'){if(work.index===work.ex.length-1){if(work.sets===0){toast('Catat minimal satu set sebelum menyelesaikan sesi.');return}finish()}else{work.index++;elapsed=0;running=false;rest=0;player()}}if(b.id==='remind'){data.reminder=$('#reminder').value;save();toast('Waktu pilihan disimpan.')}if(b.id==='info'){$('#modal-content').innerHTML='<div class="eyebrow">STREAKIN / PROTOTYPE 01</div><h2>Ruang untuk bergerak.</h2><p>Prototipe interaktif dengan data lokal di browser. Belum ada akun, sinkronisasi server, atau notifikasi otomatis.</p><p>Tujuan hosting akhir: Jagoan Hosting + Webuzo, streakin.my.id.</p><p>Pose referensi tersedia di Orange Guy Library. Ilustrasi latihan belum seluruhnya dipetakan.</p>';$('#modal').showModal()}if(b.classList.contains('close'))$('#modal').close()});render();
